sys_script_include.script:
var AcademicStructureRefQual = Class.create();

AcademicStructureRefQual.prototype = {

    initialize: function() {},

    // --------------------------------------------------
    // COMMON HELPER: GET CURRENT EMPLOYEE
    // --------------------------------------------------

    getCurrentEmployee: function() {

        var employeeGR = new GlideRecord(
            'x_1790229_edusph_0_employee'
        );

        employeeGR.addQuery('user', gs.getUserID());
        employeeGR.addQuery('active', true);
        employeeGR.setLimit(1);
        employeeGR.query();

        if (employeeGR.next()) {
            return employeeGR;
        }

        return null;
    },


    // --------------------------------------------------
    // 83. PROGRAM - DEPARTMENT
    // --------------------------------------------------
    // Uses Coll Prog mapping to retrieve departments
    // associated with the selected Program.
    // If College is available on the current record,
    // it applies that filter as well.
    // --------------------------------------------------

    getDepartments: function(current) {

        var noRecords = 'sys_id=-1';

        if (!current) {
            return noRecords;
        }

        // Get selected College from Program form
        var collegeId = current.getValue('college');

        if (!collegeId) {
            return noRecords;
        }

        // Query College-Program mapping table
        var mappingGR = new GlideRecord(
            'x_1790229_edusph_0_department'
        );

        mappingGR.addQuery('college', collegeId);
        mappingGR.addActiveQuery();
        mappingGR.query();

        var departmentIds = [];

        while (mappingGR.next()) {

            var departmentId = mappingGR.getUniqueValue();

            // Avoid duplicate departments
            if (departmentIds.indexOf(departmentId) === -1) {
                departmentIds.push(departmentId);
            }
        }

        if (departmentIds.length === 0) {
            return noRecords;
        }

        return 'sys_idIN' + departmentIds.join(',');
    },



    // --------------------------------------------------
    // 93. SEMESTER - YEAR
    // --------------------------------------------------
    // Retrieves Academic Years that are currently valid
    // according to their start and end dates.
    // --------------------------------------------------

    getAcademicYears: function(current) {

        var noRecords = 'sys_id=-1';

        var today = gs.nowDate();

        var academicYearGR = new GlideRecord(
            'x_1790229_edusph_0_academic_year'
        );

        academicYearGR.addQuery('active', true);
        academicYearGR.addNotNullQuery('start_date');
        academicYearGR.addNotNullQuery('end_date');

        academicYearGR.addQuery('start_date', '<=', today);
        academicYearGR.addQuery('end_date', '>=', today);

        academicYearGR.query();

        var academicYearIds = [];

        while (academicYearGR.next()) {
            academicYearIds.push(
                academicYearGR.getUniqueValue()
            );
        }

        if (academicYearIds.length === 0) {
            return noRecords;
        }

        return 'sys_idIN' + academicYearIds.join(',');
    },


    // --------------------------------------------------
    // 102. LAB BATCH - SECTION
    // --------------------------------------------------
    // Retrieves Sections belonging to the logged-in
    // Employee's College.
    // --------------------------------------------------

    getLabBatchSections: function(current) {

        var noRecords = 'sys_id=-1';

        var employeeGR = this.getCurrentEmployee();

        if (!employeeGR) {
            return noRecords;
        }

        var collegeId = employeeGR.getValue('college');

        if (!collegeId) {
            return noRecords;
        }

        var sectionGR = new GlideRecord(
            'x_1790229_edusph_0_section'
        );

        sectionGR.addQuery('college', collegeId);
        sectionGR.query();

        var sectionIds = [];

        while (sectionGR.next()) {
            sectionIds.push(
                sectionGR.getUniqueValue()
            );
        }

        if (sectionIds.length === 0) {
            return noRecords;
        }

        return 'sys_idIN' + sectionIds.join(',');
    },


    // --------------------------------------------------
    // 108. COURSE OFFERING - SECTION
    // --------------------------------------------------
    // Retrieves Sections belonging to the College
    // selected on the Course Offering record.
    // --------------------------------------------------

    getCourseOfferingSections: function(current) {

        var noRecords = 'sys_id=-1';

        if (!current) {
            return noRecords;
        }

        var collegeId = current.getValue('college');

        if (!collegeId) {
            return noRecords;
        }

        var sectionGR = new GlideRecord(
            'x_1790229_edusph_0_section'
        );

        sectionGR.addQuery('college', collegeId);
        sectionGR.query();

        var sectionIds = [];

        while (sectionGR.next()) {
            sectionIds.push(
                sectionGR.getUniqueValue()
            );
        }

        if (sectionIds.length === 0) {
            return noRecords;
        }

        return 'sys_idIN' + sectionIds.join(',');
    },


    // --------------------------------------------------
    // 109. COURSE OFFERING - SEMESTER
    // --------------------------------------------------
    // Retrieves Semesters belonging to the College
    // selected on the Course Offering record.
    // --------------------------------------------------

    getCourseOfferingSemesters: function(current) {

        var noRecords = 'sys_id=-1';

        if (!current) {
            return noRecords;
        }

        var collegeId = current.getValue('college');

        if (!collegeId) {
            return noRecords;
        }

        var semesterGR = new GlideRecord(
            'x_1790229_edusph_0_semester'
        );

        semesterGR.addQuery('college', collegeId);
        semesterGR.query();

        var semesterIds = [];

        while (semesterGR.next()) {
            semesterIds.push(
                semesterGR.getUniqueValue()
            );
        }

        if (semesterIds.length === 0) {
            return noRecords;
        }

        return 'sys_idIN' + semesterIds.join(',');
    },


    // --------------------------------------------------
    // 111. COURSE OFFERING - FACULTY
    // --------------------------------------------------
    // Retrieves Employees belonging to the College
    // selected on the Course Offering record.
    // --------------------------------------------------

    getCourseOfferingFaculty: function(current) {

        var noRecords = 'sys_id=-1';

        if (!current) {
            return noRecords;
        }

        var collegeId = current.getValue('college');

        if (!collegeId) {
            return noRecords;
        }

        var employeeGR = new GlideRecord(
            'x_1790229_edusph_0_employee'
        );

        employeeGR.addQuery('college', collegeId);
        employeeGR.addQuery('active', true);
        employeeGR.query();

        var employeeIds = [];

        while (employeeGR.next()) {
            employeeIds.push(
                employeeGR.getUniqueValue()
            );
        }

        if (employeeIds.length === 0) {
            return noRecords;
        }

        return 'sys_idIN' + employeeIds.join(',');
    },


    type: 'AcademicStructureRefQual'
};
